    phrases: [
      { greek: 'Καλή όρεξη!', transcription: 'Кали орэкси!', translation: 'Приятного аппетита!', note: 'Обязательно говорят перед едой. Ответ: "Ευχαριστώ, κι εσάς!" (Спасибо, и вам!)' },
      { greek: 'Στην υγειά μας!', transcription: 'Стин ийа мас!', translation: 'За наше здоровье! / Ура! (тост)', note: 'Главный греческий тост. Обязательно смотрят в глаза при чокании — иначе 7 лет несчастья!' },
      { greek: 'Γεια μας!', transcription: 'Йа мас!', translation: 'Ура! / За нас! (неформальный тост)', note: 'Короткая версия тоста. На вечеринке с друзьями говорят именно это.' },
      { greek: 'Τι νοστιμιά!', transcription: 'Ти ностимья!', translation: 'Как вкусно! / Объедение!', note: '"Νόστιμος" = вкусный. Лучший комплимент хозяйке. За греческим столом обязательно скажи это.' },
      { greek: 'Χόρτασα', transcription: 'Хортаса', translation: 'Я наелся/наелась', note: 'Говорят когда больше не могут есть. Хозяева обычно не верят и подкладывают ещё — это норма.' },
      { greek: 'Μου αρέσει πολύ!', transcription: 'Му арэси поли!', translation: 'Мне очень нравится!', note: 'Скажи это про еду — греки растают. Искренние комплименты здесь ценятся особенно.' },
      { greek: 'Λογαριασμό, παρακαλώ!', transcription: 'Логарьязмо, паракало!', translation: 'Счёт, пожалуйста!', note: 'Фраза №1 в ресторане. Часто достаточно просто поднять руку и сказать "Παρακαλώ!"' },
      { greek: 'Να σας ζήσει!', transcription: 'На сас зиси!', translation: 'Пусть живёт! (поздравление с новорождённым / подарком)', note: 'Говорят когда поздравляют с новым ребёнком, покупкой или достижением. Буквально: "пусть живёт для вас".' },
    ]
